/** Codice "n.m" → testo letterale del sub-indice, o undefined se inesistente. */
export function testoSubIndice(codice: string): string | undefined {
  const m = /^(\d{1,2})\.(\d{1,2})$/.exec(codice);
  if (!m) return undefined;
  return SUB_INDICI_UIF_2023[Number(m[1])]?.[Number(m[2]) - 1];
}

export function contaSubIndici(): number {
  return Object.values(SUB_INDICI_UIF_2023).reduce((s, v) => s + v.length, 0);
}
